import java.io.*;
import java.util.*;

public class Cards {
    static final long MOD = 998244353;
    static long[][] stirling;
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        stirling = new long[5001][5001];
        stirling[0][0] = 1;
        for (int i = 1; i < 5001; i++) {
            for (int j = 1; j < 5001; j++) {
                stirling[i][j] = (stirling[i - 1][j - 1] + j * stirling[i - 1][j]) % MOD;
            }
        }
        String inputLine = br.readLine();
        String[] tokens = inputLine.split(" ");
        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        int k = Integer.parseInt(tokens[2]);
        long invM = modInverse(m, MOD);
        long product = 1;
        long total = 0;
        long prob = 1;
        for (int i = k; i > 0; i--) {
            product = (product * (n - (k - i))) % MOD;
            prob = (prob * invM) % MOD;
            total = (total + ((product * prob) % MOD) * stirling[k][k - i + 1]) % MOD;
        }
        System.out.println(total);
    }

    public static long modInverse(long x, long p) {
        return power(x, p - 2, p);
    }

    public static long power(long base, long exp, long p) {
        long res = 1;
        base %= p;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % p;
            base = (base * base) % p;
            exp >>= 1;
        }
        return res;
    }
}
